package com.hyrulecreatures.client;

import com.google.gson.Gson;
import com.hyrulecreatures.HyruleCreatures;
import java.io.InputStreamReader;
import java.util.*;
import net.minecraft.client.model.geom.PartPose;
import net.minecraft.client.model.geom.builders.*;

/** Model spec generated by tools/gen_assets.py. */
public final class Spec {
    public static class Part { String n, p, c; int[] uv; float[] box, pose, rot; }
    int[] tex; public float hunch; Part[] parts;
    private static final Map<String, Spec> CACHE = new HashMap<>();

    public static Spec get(String id) {
        return CACHE.computeIfAbsent(id, k -> new Gson().fromJson(new InputStreamReader(
                Spec.class.getResourceAsStream("/assets/" + HyruleCreatures.ID + "/specs/" + k + ".json")), Spec.class));
    }

    public List<String> names() { return Arrays.stream(parts).map(p -> p.n).toList(); }
    public String parentOf(String n) { return Arrays.stream(parts).filter(p -> p.n.equals(n)).findFirst().get().p; }

    public LayerDefinition layer() {
        MeshDefinition m = new MeshDefinition();
        Map<String, PartDefinition> defs = new HashMap<>();
        for (Part p : parts) {
            PartDefinition parent = p.p == null ? m.getRoot() : defs.get(p.p);
            defs.put(p.n, parent.addOrReplaceChild(p.n, CubeListBuilder.create().texOffs(p.uv[0], p.uv[1])
                    .addBox(p.box[0], p.box[1], p.box[2], p.box[3], p.box[4], p.box[5]),
                    PartPose.offsetAndRotation(p.pose[0], p.pose[1], p.pose[2], p.rot[0], p.rot[1], p.rot[2])));
        }
        return LayerDefinition.create(m, tex[0], tex[1]);
    }
}
